    <h1>Consented Webcam Photo Booth</h1>
    <p>Click "Start Camera" to enable your webcam. Your video feed will only be visible locally.</p>

    <video id="video" width="640" height="480" autoplay></video>
    <canvas id="canvas" width="640" height="480" style="display:none;"></canvas>

    <div class="controls">
        <button id="startBtn">Start Camera</button>
        <button id="captureBtn" disabled>Capture Photo</button>
        <button id="downloadBtn" disabled>Download Photo</button>
    </div>

    <div id="status">Camera access not started</div>
    <img id="photo" alt="Your photo will appear here" style="max-width: 100%; margin-top: 20px;">

    <script>
        const video = document.getElementById('video');
        const canvas = document.getElementById('canvas');
        const photo = document.getElementById('photo');
        const startBtn = document.getElementById('startBtn');
        const captureBtn = document.getElementById('captureBtn');
        const downloadBtn = document.getElementById('downloadBtn');
        const status = document.getElementById('status');

        // Request camera access with user consent
        startBtn.addEventListener('click', async () => {
            try {
                status.textContent = "Requesting camera access...";
                const stream = await navigator.mediaDevices.getUserMedia({ 
                    video: { 
                        width: { ideal: 1280 },
                        height: { ideal: 720 }
                    } 
                });

                video.srcObject = stream;
                startBtn.disabled = true;
                captureBtn.disabled = false;
                status.textContent = "Camera active. Click 'Capture Photo' to take a picture.";
            } catch (err) {
                console.error("Error accessing camera:", err);
                status.textContent = "Camera access denied or unavailable. Please check permissions.";
                startBtn.disabled = false;
            }
        });

        // Capture photo
        captureBtn.addEventListener('click', () => {
            const context = canvas.getContext('2d');
            context.drawImage(video, 0, 0, canvas.width, canvas.height);
            const dataUrl = canvas.toDataURL('image/png');
            photo.src = dataUrl;
            photo.alt = "Captured photo";

            downloadBtn.disabled = false;
            status.textContent = "Photo captured. Click 'Download Photo' to save.";
        });

        // Download photo
        downloadBtn.addEventListener('click', () => {
            const link = document.createElement('a');
            link.download = `webcam-photo-${Date.now()}.png`;
            link.href = photo.src;
            link.click();
            status.textContent = "Photo downloaded.";
        });
    </script>
</body>
</html>
```

### Key Security & Ethical Features:
1. **Explicit User Consent**: Camera access requires a user action (clicking "Start Camera")
2. **Browser Security**: Uses standard `getUserMedia()` API with browser

